    "caseText": "FPの大森さんは、不動産価格を試算する3つの基本手法の違いを、資料の表で確認している。対象は手法と用語の一般的な対応であり、実在する物件の鑑定価格を確定するものではない。原価法では、今その不動産を再び調達するとした場合の費用（ア）を出発点に、経年等による価値の減少を修正する。（イ）は、似た売買事例の価格を取引事情・時点や地域・個別の違いに応じて修正し、比較して試算する手法である。収益還元法では、将来見込まれる純収益を価格時点の価値である（ウ）にそろえて合計する考え方を用いる。特定の還元利回り・割引率・DCF法の詳細な計算は与えていない。",
    "question": "資料の空欄（ア）・（イ）・（ウ）の組合せとして、最も適切なものはどれか。",
    "kind": "choice",
    "choices": [
      "再調達原価／原価法／将来価値",
      "再調達原価／取引事例比較法／現在価値",
      "比準価格／取引事例比較法／現在価値"
    ],
    "answer": 1,
