    "caseTitle": "代襲相続と相続税",
    "caseText": "【2026年4月1日基準の独自演習】岡本さんの相続人は妻、生存する子2人、先に亡くなった別の子の唯一の子である孫1人。孫は代襲相続人で、相続放棄・養子はない。本人負担の生命保険の死亡保険金2600万円を妻だけが受領。妻が取得する自宅敷地は300㎡、評価額7500万円で、特定居住用宅地等の小規模宅地特例の要件をすべて満たす。別問の相続税総額では課税遺産総額を12000万円と与える。速算表は1,000万円以下10％／控除0、3,000万円以下15％／50万円、5,000万円以下20％／200万円、1億円以下30％／700万円。相続開始日は2026年4月1日とする。妻は法律上の配偶者で、生存する子2人は実子、孫は死亡した実子の唯一の子とする。死亡保険は被相続人本人が全額保険料を負担し、被保険者も本人で、妻が一時金を受け取る。他の死亡保険金はない。自宅敷地は相続開始直前の本人の居住用で、妻が全体取得し、特例適用前の評価額を与え、必要書類を添付した申告等の手続要件を満たす。他に特例を選択する宅地はない。別問の課税遺産総額は各控除や加算等の処理後に与えた独立の計算条件で、基礎控除や死亡保険金を再度差し引かない。計算する相続税総額は配偶者軽減等の個別税額控除前である。",
    "question": "死亡者が所得税の確定申告を要する場合の準確定申告期限と、相続税の原則の申告期限の組合せはどれか。",
