    "question": "賃貸経営について、各記述が適切なら○、不適切なら×を選びなさい。①は所有者本人が自己物件を貸すだけの場面、②は業者への一括賃貸を検討する独立した場面とする。③の計算用に、年間賃料等収入360万円、年間運営費120万円（借入金の元利返済額を含まない）、年間元利返済額200万円を与える。この問のDSCRは、年間営業純利益（賃料等収入－運営費）を年間元利返済額で割るものとする。税引後手取りや将来の空室・修繕発生を予測する問題ではない。",
