    "caseText": "【2026年4月1日基準の独自演習】遠藤さんは近隣商業地域にある土地400㎡へ賃貸マンションを建てる。指定建蔽率80％・指定容積率400％、前面道路1本の幅員6m、容積率の道路係数6/10。道路後退・角地加算・防火等による建蔽率緩和・その他の特例はない。建物は地主本人が所有し貸し付ける。相続税評価では土地の自用地価額8000万円、借地権割合60％、借家権割合30％、賃貸割合100％。小規模宅地等の特例は考慮しない。容積率不算入となる床面積はなく、容積率算定に用いる延べ面積の上限を計算する。賃貸建物は地主本人が一棟を所有し、区分所有マンションや社宅ではなく、借家権の目的となる一般の貸家とする。土地評価の資料は建築完了後の貸付け・課税時点を仮定した独立の与件で、計画段階で直ちに貸家建付地となるとはしない。賃貸割合は各独立部分の床面積により求めた割合で、一時的空室等の調整も済んだ与件とする。実際の建築可否・他の高さ規制等や路線価の選定は計算対象外。",
    "question": "各欄に当てはまる項目を語群から選び、記号（ア・イ・ウ…）で答えなさい。①は、賃貸業務のための建物の取得・登記に係る不動産取得税と登録免許税について、2026年中に納税義務が具体的に確定して納付した場合の不動産所得上の取扱いを問う。取得価額等との二重計上はない。②は独立した制度確認で、賦課期日1月1日に住宅用地の要件を満たし、住宅1戸につき200㎡までの小規模住宅用地と判定済みの部分について、固定資産税の本則課税標準額を価格の何分の1とするかを問う。③は共通資料の建築完了後の貸付け・課税時点の独立した与件による貸家建付地評価額を問う。②の価格は固定資産税の価格で、③の相続税の自用地価額とは別である。",
    "kind": "wordbank_number",
    "choices": [],
    "explanation": "①はアの算入できる。業務用の土地・建物に係る不動産取得税や登録免許税は、指定条件で各種所得の必要経費となり、イの一律算入できないという説明は当たりません。住宅の自用取得や、特許権等の登録免許税の別取扱いと区別します。②はエの6。固定資産税の小規模住宅用地の本則課税標準は価格の1/6で、ウの1/3は同じ区分の都市計画税などとの混同、オの200は面積区分の㎡数との混同です。実際の課税標準に対する負担調整や税額の計算は行わず、税率や納税額を1/6とする意味ではありません。③はカの6560万円。8000×（1－0.6×0.3×1）＝6560万円。キの7568万円は借家権割合0.3を余分にもう一度掛けた誤り、クの6080万円は借地権割合0.6を建蔽率0.8と取り違えた誤りです。賃貸割合は床面積の割合を使い、与件の100％を用います。貸宅地・社宅・区分所有財産とは区別し、相続税の小規模宅地等の特例は適用しません。",
