    "question": "相続・事業承継について、各記述が適切なら○、不適切なら×を選びなさい。①は父が公正証書遺言を作る場面。②は独立した条件として、遺留分算定の基礎財産は贈与加算・債務控除等の処理後16000万円、権利放棄なしとする（相続税の課税遺産総額12000万円とは別）。③は対象会社・後継者等の要件、所定の全員合意、経済産業大臣の確認、家庭裁判所の許可審判の確定等、特例の適用要件・手続を満たすものとする。④は独立した条件として、特例前5000万円・400㎡の宅地全部が特定同族会社事業用宅地等に該当し、相続税申告等を含む全適用要件を満たし、他の宅地との選択はないものとする。",
