    "explanation": "①は×。推定相続人は公正証書遺言の証人になれず、家族全員の了承でこの制限はなくなりません。推定相続人・受遺者と、その配偶者や直系血族等も証人から除外されます。②は○。この家族構成の遺留分全体は基礎財産の1/2、子1人の法定相続分は1/4なので、16000×1/2×1/4＝2000万円。法定相続分だけを掛ける4000万円や、妻の遺留分4000万円と混同しません。これは遺留分額であり、取得済み財産等も考慮する具体的な遺留分侵害額・請求額とは別です。③は○。対象となる中小会社の株式等についての除外合意と固定合意の制度概要です。後継者単独の意思や私的合意だけで有効になるという意味ではなく、与件の要件・確認・許可確定等が前提です。個人事業用資産にも同じ固定合意が一律にあるとは述べていません。④は×。特定同族会社事業用宅地等は限度400㎡・減額割合80％で、全400㎡の条件なら5000×(1－0.8)＝1000万円。2500万円は減額割合を50％と取り違えた値です。実際の事業・法人・取得者・保有継続等の適用判定は与件で充足とし、すべての会社用地に自動適用されるという意味ではありません。",
