    "caseText": "【2026年4月1日基準の独自演習】遠藤さんの父は非上場の製造会社を経営し、株式の承継を検討している。本問では財産評価基本通達上の「中会社の小」、特定の評価会社には該当せず、原則的評価方式を用いる。資本金等の額を1株50円換算した比準要素は、自社／類似業種の順に配当6円／5円、利益30円／20円、簿価純資産240円／200円。類似業種株価500円。実際の1株当たり資本金等の額100円、純資産価額方式の1株評価額2400円。類似業種比準価額＝類似業種株価×3要素の比率の平均×0.6×（実際の1株資本金等の額／50円）。併用割合L＝0.6を採用する。中間計算の端数処理はせず最終値を求める。別途、父の相続人は妻と子2人、課税遺産総額は12000万円。速算表（取得額：税率／控除）は1,000万円以下10％／0、3,000万円以下15％／50万円、5,000万円以下20％／200万円、1億円以下30％／700万円。個別税額控除前を計算する。課税時期は2026年4月1日とし、取得者は原則的評価方式を適用する同族株主等に該当すると仮定する。会社規模・特定評価会社非該当・純資産価額・比準要素・併用割合は判定済みの計算用与件で、実在会社の業種別株価や規模を新たに認定する問題ではない。指定算式による計算値を問い、実際の株式評価の端数規定・別の選択方式との比較は対象外。父の相続人は法律上の妻と実子2人で放棄・養子・代襲なし。課税遺産総額は控除処理後に与えた別の独立条件で、株価の計算値をこの総額へ加算せず、基礎控除も再度差し引かない。相続税計算の解答表は、基礎控除額（ア）万円、子1人の法定相続分に応ずる税額（イ）万円、相続税の総額（ウ）万円とする。",
