    "caseTitle": "事業用土地の建築規制",
    "caseText": "【2026年4月1日基準の独自演習】東雲社は一体の敷地に新社屋を計画している。敷地は近隣商業地域300㎡（指定建蔽率80％、指定容積率400％）と第一種中高層住居専用地域200㎡（指定建蔽率60％、指定容積率200％）にまたがる。前面道路は1本で幅員6m、道路幅員による容積率制限の係数は近隣商業地域6/10、第一種中高層住居専用地域4/10とする。建蔽率は各区域の面積に各指定建蔽率を乗じた面積を合計し、容積率は各区域で指定容積率と道路幅員による限度の小さい方を用いて面積を合計する。角地・防火地域の耐火建築物等による建蔽率緩和、容積率の特例、道路後退、複数道路その他の緩和はない。地上部分の建築面積と容積率算入延べ面積だけを求める。",
    "question": "近隣商業地域の説明として適切なものはどれか。",
