    "caseTitle": "老齢年金と自営業者の備え",
    "caseText": "自営業の安藤さん（男性、1981年2月2日生まれ）は、2026年4月1日現在45歳で、配偶者と子はいない。厚生年金の加入実績は1999年4月から2024年3月までの300月で、このうち20歳前の1999年4月〜2001年1月が22月、20歳以上の2001年2月〜2024年3月が278月である。2003年3月以前の48月の平均標準報酬月額は240,000円、2003年4月以後の252月の平均標準報酬額は420,000円で、いずれも計算用に再評価済みの額とする。退職後の2024年4月〜2025年3月は国民年金第1号の未納12月で、免除・猶予・学生納付特例ではない。2025年4月〜2026年3月は第1号として12月納付済みであり、2026年4月〜2041年1月の178月も第1号として全額納付する見込みとする。各期間は両端の月を含み、重複も他の加入期間もない。60歳到達は2041年2月1日、65歳到達は2046年2月1日で、2024年4月以後は厚生年金に再加入しないものとする。問1は2026年4月1日の制度と2026年度価額を固定した将来仮定の計算であり、2046年度の実際の支給額を予測するものではない。計算用の老齢基礎年金満額は847,300円、定額部分の単価は1,766円、生年月日に応じた率は1.000、報酬比例乗率は7.125/1000と5.481/1000とする。問1では本来水準の報酬比例部分と経過的加算だけを老齢厚生年金に含め、従前額保障・再評価率の再計算・加給年金・振替加算・基金の代行・在職支給停止・繰上げ繰下げ・付加年金は計算しない。60歳以後の任意加入や未納分の後納も加えない。問2・問3は2026年4月1日の制度を固定した別々の検討である。問2③の付加保険料納付と問3の国民年金基金加入は同時に行う仮定ではなく、問1の年金額に加算しない。",
    "question": "安藤さんが2026年に国民年金基金へ加入する場合の説明について、空欄①〜③に合う項目を語群から選び、記号で答えなさい。加入資格を満たす国民年金第1号被保険者で、保険料免除等はなく、付加保険料は納付しない。基金の1口目はA型・B型のいずれかの〔①〕年金を選ぶ。A型で加入者が保証期間を終える前に死亡し、所定の遺族・支給要件を満たすと、〔②〕が支給される。2026年中に本人が負担して実際に支払った基金掛金の全額は、所得税の〔③〕の対象となる。税率や税額、基金掛金の限度額は問わない。",
    "kind": "wordbank_number",
    "choices": [],
    "explanation": "①はア（終身）。基金の1口目は終身年金A型・B型から選びます。イ（確定）とウ（有期）は1口目の指定に合いません。確定年金型が制度に存在しないと述べているのではありません。②はエ（遺族一時金）。A型の保証期間終了前の死亡等では所定の遺族への一時金があり、オ（遺族年金）のように継続する年金や、カ（障害給付）と取り違えません。B型を含む全死亡時に同じ額を保証するという説明ではありません。③はキ（社会保険料控除）。本人が負担してその年に実際に支払った基金掛金が全額対象です。ク（小規模企業共済等掛金控除）はiDeCo等の別制度の控除で、ケ（生命保険料控除）にも分類しません。所得控除であって、掛金全額がそのまま税金から返る税額控除ではありません。2026年の条件であり、後年の掛金限度額改正等を遡及適用していません。",
