    "case": 7,
    "caseTitle": "株式指標と取引ルール",
    "caseText": "【2026年4月1日基準の独自演習】安藤さんの家族は株式投資を検討している。上場会社の株価3000円、発行済株式数100万株、当期純利益250,000,000円、自己資本2,000,000,000円。自己株式・潜在株式・株式分割はない。注文方法と価格・時間優先の基本原則も確認したい。指値の買い注文について、通常のザラバ取引を想定し、寄り付き・引け・特別な配分等は考慮しない。財務数値は同じ決算期・普通株式を対象とし、EPS/BPSは設例の株数で計算する。単位は利益・自己資本の総額が円、株価や1株当たりの指標が円/株、PER/PBRが倍である。実際の投資判断、将来利益、税・手数料は計算しない。この3問の追加与件として、負債総額は800000000円、期首自己資本は2000000000円とし、期首・期末の自己資本は株主資本および純資産と同額とする。ETF・NISAの制度確認はこの会社の財務計算とは独立した2026年の条件として扱う。",
    "question": "資料の数値から①PBR、②ROE、③負債比率を求めなさい。PBRは株価÷1株当たり純資産、ROEは税引後の当期純利益÷期首・期末自己資本の平均×100、負債比率は負債総額÷期末自己資本×100とする。小数第3位を四捨五入して小数第2位まで求め、単位を付けず入力する（1.50と1.5等は同値）。負債比率と、負債を総資産で割る比率を区別する。",
    "kind": "multi_numeric",
    "choices": [],
    "explanation": "①は1.50倍。1株当たり純資産は2000000000÷1000000＝2000円/株、PBR＝3000÷2000＝1.5倍です。②は12.50％。平均自己資本は(2000000000＋2000000000)÷2＝2000000000円なので、250000000÷2000000000×100＝12.5％。③は40.00％。800000000÷2000000000×100＝40％です。総資産は負債と純資産の合計2800000000円ですが、これを分母にした約28.57％は指定した負債比率ではありません。旧問のPERは、EPS＝250000000÷1000000＝250円/株より3000÷250＝12倍で、PBRの1.5倍と区別します。比率で100倍を忘れる0.125や0.4を％の解答としません。通常ザラバの買い指値は高い価格が優先し、同価格なら先の注文が優先するという旧問の知識も変わりません。これらの指標だけで将来利益や割安を保証しません。",
    "topic": "PBR・平均自己資本ROE・負債比率",
