    "caseText": "【2026年4月1日基準の独自演習】安藤さんの家族は株式投資を検討している。上場会社の株価3000円、発行済株式数100万株、当期純利益250,000,000円、自己資本2,000,000,000円。自己株式・潜在株式・株式分割はない。注文方法と価格・時間優先の基本原則も確認したい。指値の買い注文について、通常のザラバ取引を想定し、寄り付き・引け・特別な配分等は考慮しない。財務数値は同じ決算期・普通株式を対象とし、EPS/BPSは設例の株数で計算する。単位は利益・自己資本の総額が円、株価や1株当たりの指標が円/株、PER/PBRが倍である。実際の投資判断、将来利益、税・手数料は計算しない。この3問の追加与件として、負債総額は800000000円、期首自己資本は2000000000円とし、期首・期末の自己資本は株主資本および純資産と同額とする。ETF・NISAの制度確認はこの会社の財務計算とは独立した2026年の条件として扱う。",
    "question": "ETFの説明の空欄①〜③に合う項目を語群から選び、記号で答えなさい。①は、信託報酬率が正の値で定められたETFの運用管理費用で、信託報酬が〔①〕。②は、日本の居住者が国内証券会社の源泉徴収あり特定口座で保有する国内公募株式ETFについて、譲渡益と同口座で受け入れる普通分配金に対する2026年の所得税等・住民税の合計税率〔②〕を問う。NISA・大口株主等・外国税・元本払戻し・損益通算は対象外とする。③は、原指標の日々の変動率を正の2倍とする指数への連動を目指す〔③〕型を問う。2日以上の騰落率やETFの実際の市場価格まで常に2倍になるという意味ではない。",
    "kind": "wordbank_number",
    "choices": [],
    "explanation": "①はア（かかる）。本問は正の信託報酬率を定めたETFなので運用中の負担があり、売買委託手数料と同一ではありません。イ（かからない）は与件に反します。ETFの全銘柄の費用が同額と述べているのではありません。②はウ（20.315％）。2026年は所得税15％に対する復興特別所得税15％×2.1％＝0.315％と住民税5％を合わせます。オ（22.1％）は復興特別所得税2.1％を譲渡益へ直接足した誤りです。エ（20.42％）は20％×1.021という国税の計算に相当し、本問の15％を基礎とする国税と住民税の合算ではありません。実際の税額や申告の有利不利、2027年以後の税内訳は計算しません。③はカ（レバレッジ）。キ（インバース）は原指標と逆方向を目指すもの、ク（元本保証）は価格変動リスクを無くす説明、ケ（毎月分配）は分配頻度であり、正の2倍という指数の性質を示しません。2日以上では複利効果があるため原指標の騰落率の2倍とは限らず、信託報酬や追随誤差等によりETF市場価格の騰落率も目標と一致する保証はありません。",
