    "caseText": "【2026年4月1日基準の独自演習】安藤さんの家族は株式投資を検討している。上場会社の株価3000円、発行済株式数100万株、当期純利益250,000,000円、自己資本2,000,000,000円。自己株式・潜在株式・株式分割はない。注文方法と価格・時間優先の基本原則も確認したい。指値の買い注文について、通常のザラバ取引を想定し、寄り付き・引け・特別な配分等は考慮しない。財務数値は同じ決算期・普通株式を対象とし、EPS/BPSは設例の株数で計算する。単位は利益・自己資本の総額が円、株価や1株当たりの指標が円/株、PER/PBRが倍である。実際の投資判断、将来利益、税・手数料は計算しない。この3問の追加与件として、負債総額は800000000円、期首自己資本は2000000000円とし、期首・期末の自己資本は株主資本および純資産と同額とする。ETF・NISAの制度確認はこの会社の財務計算とは独立した2026年の条件として扱う。",
    "question": "2026年のNISAについて、各記述が適切なら○、不適切なら×を選びなさい。利用者は2026年1月1日時点で30歳の日本居住者で、口座開設等の要件を満たす。②の残高は2024年以降のNISAの取得金額による簿価で、売却・金融機関変更や2023年までの旧NISAは考慮しない。②は制度上の保有限度の判定であり、年間枠や積み上げに必要な年数を問うものではない。④はNISAの成長投資枠で保有する国内上場普通株式・国内上場ETFについて、日本での配当・分配金課税を問う。2027年以降の未成年者向け制度は扱わない。④のETFは問5のレバレッジ型とは別のNISA対象商品とする。",
    "kind": "multi_choice",
    "choices": [],
    "explanation": "①は○。2026年の年間枠は120万円と240万円で合計360万円です。非課税保有限度額1800万円と年間枠は別で、1800万円を1年に買える意味ではありません。②は×。成長投資枠の保有限度額は総枠1800万円の内数として1200万円です。1800－300＝1500万円という差額だけで成長枠の上限を超えることはできません。300＋1200＝1500万円でも総枠に300万円の余地が残りますが、その余地で成長枠の上限が増えることはありません。1200万円をその年に買い付けられるという意味ではありません。③は×。つみたて投資枠の投資対象は長期の積立・分散投資に適した一定の投資信託です。個別の上場株式を直接買う場面は、対象商品の条件を満たす成長投資枠と区別します。④は○。株式数比例配分方式で証券会社等を経由して受け取る必要があり、発行会社から直接受け取る方法ではこの非課税扱いになりません。非上場の通常の投資信託の分配金受取と同一視しません。2027年以降の未成年者向け制度を2026年の年齢要件へ遡って適用していません。",
    "topic": "NISAの年間枠・成長枠内数・対象商品・配当受取",
