    "caseText": "会社員の遠藤さん（1965年4月15日生まれ）は、2025年4月末に定年退職し、翌月から同じ会社で継続雇用されている。退職金の計算対象となる勤続期間は1994年9月1日〜2025年4月30日の30年8カ月で、2025年中に受けた通常の退職手当は2,500万円である。受給時に退職所得の受給に関する申告書を提出済みで、役員等の期間・障害を直接原因とする退職・他の退職一時金や確定拠出年金一時金との重複調整はない。2025年分の給与収入は継続雇用後の分を含め年間合計960万円、不動産所得は白色申告の国内賃貸物件からの46万円の黒字である。国内上場株式を金融商品取引業者を通じて売却し、源泉徴収あり特定口座内で28万円の譲渡損失が生じた。NISA・相対取引・一般株式等の損失ではなく、その年に通算できる上場株式等の配当や他の譲渡益はない。妻（1971年6月10日生まれ）の2025年分の収入は給与115万円だけで、長女（2004年7月10日生まれ）は大学生で2025年中の収入・所得がない。全員国内居住で同居し生計を一にしており、妻は法律上の配偶者、妻と長女はいずれも事業専従者ではない。長女の扶養控除を他の人と重複して受けることはなく、全員障害者ではない。年齢は2025年12月31日現在で本人60歳・妻54歳・長女21歳とする。記載以外の所得や繰越損失はなく、給与所得者の特定支出控除はない。法令基準日は2026年4月1日で、対象は2025年分の所得税である。2025年分に適用される給与所得控除の最低額65万円、配偶者・扶養親族の所得要件58万円以下を用い、2026年分以後の金額を遡って使わない。問8の給与所得では23歳未満の扶養親族がいる場合の所得金額調整控除を適用する。所得控除や所得税額・住民税額を求める問題ではない。問9②は2025年分から所定の付表・明細書を付けて申告し、その後も連続申告する等の全手続要件を満たす場合とする。",
    "question": "2025年分の①所得金額調整控除後の給与所得金額、②総所得金額を、万円単位の数値だけで入力しなさい。給与収入850万円超の給与所得控除額は195万円とする。所得金額調整控除は適用要件を判定し、該当するときは（給与収入と1,000万円の少ない方－850万円）×10％を給与所得から控除する。②は「総所得金額等」や「合計所得金額」と区別し、退職所得を加算しない。",
