    "explanation": "①は×。単純承認に家庭裁判所への承認の申述を必須とはしません。限定承認や相続放棄の申述と区別します。熟慮期間の起算・伸長や法定単純承認に当たる処分行為等は別の判定です。②は○。法定相続人はW・S・Dを代襲するGの3人で、先に死亡したDを4人目に数えません。非課税限度額は500万円×3＝1,500万円。相続人Wが唯一の保険金受取人なので、2,400－1,500＝900万円が課税対象です。2,400万円全額や500万円だけを控除した1,900万円は誤りで、非課税枠を基礎控除と混同しません。③は○。子Dの死亡により代襲相続人となった直系卑属Gは2割加算の対象から除かれます。代襲でない孫への遺贈や孫養子の一般的な取扱いと混同しません。これは本設例の限定照合で、民法の全条文・全例外や実際の相続手続を包括監修したものではありません。",
