    "question": "①遺産に係る基礎控除額、②課税遺産総額16,000万円を法定相続分で取得したと仮定したGさんの税額、③相続税の総額を、それぞれ万円単位で数値だけ入力しなさい。課税遺産総額は基礎控除反映後で、③は実際の取得割合への配分・配偶者の税額軽減前の金額とする。速算表：取得金額1,000万円以下10％・控除0、3,000万円以下15％・50万円、5,000万円以下20％・200万円、1億円以下30％・700万円。",
