    "explanation": "①は4,800万円。法定相続人3人なので3,000＋600×3＝4,800万円で、先に死亡したDを含む5,400万円ではありません。財産表はWが3,200＋2,040＋1,200＋900＝7,340、Sが3,000＋900＋1,500＝5,400、Gが8,060、合計20,800万円。ここから4,800を引いた課税遺産総額が与件16,000万円と一致します。②は600万円。妻1/2、長男1/4、長女の枝を代襲するG1/4なので、Gの仮取得額4,000万円×20％－200万円＝600万円。Gが実際に取得した8,060万円へ直ちに速算表を適用する計算ではなく、最終納税額でもありません。③は2,900万円。Wの仮取得8,000万円は8,000×30％－700＝1,700万円、SとGは各600万円で合計1,700＋600＋600＝2,900万円。16,000万円から再び基礎控除4,800万円を引かず、Gの仮税額だけに2割加算もしません。Wの配偶者軽減を総額計算の段階で控除することもありません。実際の各人への配分・税額控除後の最終納税額や他の特例は本問の計算範囲外です。",
