    "caseText": "【2026年4月1日基準の独自演習】会社員の森さん（54歳）は生命保険を見直す。死亡後の生活・教育・葬儀等の必要資金総額5600万円、遺族年金の見込総額・死亡退職金・預貯金など充当可能資金の合計2500万円。加入契約は終身保険500万円、定期保険特約1300万円。疾病死亡ではこの2保障が支払対象となり、事故死亡限定の災害割増特約500万円は支払対象外。すべて設例上の仮定で、その他給付はない。森さんは国内の市町村に住所を有する医療保険加入者である。充当可能資金には既契約の生命保険金を含めず、必要保障額は既契約を差し引く前の額と、差し引いた後の追加必要額を区別する。妻が死亡保険金受取人で、疾病死亡の給付条件と免責条件は満たすと仮定する。必要資金・遺族年金等は制度上の給付額を新たに計算する数値ではなく、設例で与える見込総額である。",
