    "caseText": "【2026年4月1日基準の独自演習】高橋さんの2026年分の給与所得は610万円。20年満期の平準払養老保険を満期一時金として800万円受領し、正味払込保険料は660万円。保険料負担者・受取人はいずれも本人。他の一時所得はない。本人が生計を一にする家族の対象医療費60万円を支払い、その同じ医療費を補填する給付金は15万円。新契約の一般生命保険料10万円、介護医療保険料12万円、控除要件を満たす新個人年金保険料9万円も支払った。他の所得はなく、医療費の補填超過はない。保険料控除の3契約はいずれも2012年1月1日以後の別契約で、控除証明書により記載の区分・金額が確認でき、剰余金・割戻金を差し引いた年間支払額である。個人年金保険料は所得税の控除要件を満たす。本人には23歳未満の扶養親族はなく、旧契約保険料もない。給与所得610万円は給与所得控除等を適用した後の与件で、給与収入とは区別する。",
