    "caseText": "会社員の田中さんについて、2026年4月1日現在の制度で2026年分の所得を計算する独自設例である。給与収入は源泉徴収前の支払金額で820万円とし、給与所得控除はこの収入区分に適用される「収入×10％＋110万円」を用いる。所得金額調整控除・特定支出控除は適用なし。本人がその年中に、自己および生計を一にする家族の控除対象医療費82万円を実際に支払う。内訳は、入院給付金の給付目的となる入院医療費12万円と、その給付の目的ではない他の医療費70万円である。入院給付金22万円は上記の入院医療費だけを補てんするもので、他に医療費を補てんする給付・保険金はない。総所得金額等は200万円以上であり、通常の医療費控除を計算し、セルフメディケーション税制は選択しない。本人が保険料を全額負担した生命保険の満期保険金750万円を、本人が一時金で受け取る。その満期保険金の収入を得るために本人が支出した正味払込保険料は600万円で、契約期間は16年、保険料は平準払いとする。この満期金は上記の入院給付金とは別の給付であり、医療費を補てんするものではない。源泉分離課税の対象となる金融類似商品には該当せず、他の一時所得・他の所得や収入を得るための追加費用はない。本問では所得金額と医療費の所得控除額を求め、所得税額・住民税額や手取額は計算しない。",
    "question": "2026年4月1日現在の制度について、次の説明の適否の組合せはどれか。①医療費控除は、計算した所得税額から控除額を直接引く税額控除である。②通常の医療費控除は年末調整では適用できず、確定申告で適用を受ける。③医療費を補てんする保険金等は、その給付の目的となる医療費を限度として差し引き、超過額を他の医療費からは差し引かない。",
    "kind": "choice",
    "answer": 1,
    "explanation": "①×：医療費控除は所得控除であり、税額から直接差し引く税額控除ではありません。②○：通常の医療費控除は年末調整の対象ではなく、確定申告で適用を受けます。③○：補てん対象の医療費が差引きの上限です。給付金がその医療費を超えても、余剰を別の医療費から差し引きません。",
