    "reviewNote": "Ver.99：給与の収入区分、生計同一家族の医療費と補てん対象別の差引き、満期金の実際の負担者/受取人、一時所得算入額を限定確認。包括監修未完了。 Ver.175：指定条件に基づく全選択肢の誤答根拠を限定再確認・独立検算。新法改正/ID初回/追加移行へ加算しない。共通設例の全論点監修ではない。",
